            validIndices.push(i);
        }
    }

    const cleanX = validIndices.map(i => xData[i]);
    const cleanY = validIndices.map(i => yData[i]);

    // Store current plot data with numeric x values
    currentPlotData = {
        title,
        xData: cleanX,
        yData: [...cleanY],
        xLabel,
        yLabel,
        color,
        rawYData: [...cleanY],
        isCustomPlot: false
    };

